def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if k <= 0 or n <= 1:
        return [0] * n

    vals = sorted(set(a), reverse=True)
    rank = {v: i for i, v in enumerate(vals, 1)}
    ranks = [rank[x] for x in a]
    m = len(vals)

    bit = [0] * (m + 1)
    res = [0] * n

    for i, r in enumerate(ranks):
        s = 0
        idx = r - 1
        while idx > 0:
            s += bit[idx]
            idx &= idx - 1
        res[i] = s

        if i >= k:
            old_r = ranks[i - k]
            if old_r != r:
                idx = r
                while idx <= m:
                    bit[idx] += 1
                    idx += idx & -idx
                idx = old_r
                while idx <= m:
                    bit[idx] -= 1
                    idx += idx & -idx
        else:
            idx = r
            while idx <= m:
                bit[idx] += 1
                idx += idx & -idx

    return res
